30	// Each command's release tier decides whether it shows in `--help`:
31	//   Release -- the finished, user-facing product surface (always listed).
32	//   Hidden  -- a stable dispatch slot for an unfinished ROADMAP feature; never
33	//              listed (explicit invocation still hits the "not yet implemented"
34	//              stub), so the product never advertises half-built work.
35	// Developer build/test/state-diff tooling lives in scripts/, not the binary.
36	enum class Tier { Release, Hidden };
37	
38	// Dispatch table: name + tier only. The display strings (briefs, modes,
39	// options) live in the help model below -- one source per concern, no
40	// duplication. `find` validates a command for dispatch; the tier keeps
41	// unfinished commands out of `--help`.
42	struct Subcommand {
43	  std::string_view name;
44	  Tier tier;
45	};
46	
47	constexpr Subcommand kSubcommands[] = {
48	    {"run", Tier::Release},    {"list", Tier::Release},
49	    {"doctor", Tier::Release}, {"profile", Tier::Hidden},
50	    {"cluster", Tier::Hidden}, {"archive", Tier::Hidden},
51	    {"replay", Tier::Hidden},  {"estimate", Tier::Hidden},
52	};
53	
54	const Subcommand* find(std::string_view name) {
55	  for (const Subcommand& s : kSubcommands)
56	    if (s.name == name) return &s;
57	  return nullptr;
58	}
59	
60	// ---- help model: the user-facing surface rendered as a command tree --------
61	//
62	// `run`'s two subcommand groups -- the modes (the composition axis) ...
63	struct ModeRow {
64	  const char* name;
65	  const char* brief;
66	};
67	constexpr ModeRow kRunModes[] = {
68	    {"fast", "QEMU only -- functional, full speed"},
69	    {"cycle", "one cycle-accurate engine, from reset"},
70	    {"hybrid", "QEMU fast-forwards, then vsim measures the ROI"},
71	};
72	
73	// `list`'s targets. `fixtures` (internal test ELFs) is a developer target,
74	// shown only under ANDESIM_DEV; the product lists user-facing models/engines.
75	struct TargetRow {
76	  const char* name;
77	  const char* brief;
78	  bool dev;
79	};
80	constexpr TargetRow kListTargets[] = {
81	    {"models", "the modes and their engines", false},
82	    {"engines", "discovered cycle-accurate engines", false},
83	    {"fixtures", "internal test ELFs (developer target)", true},
84	};
85	
86	// ... and `run`'s options. `tag` marks a required option (and WHEN it is
87	// required); `indent` nests an option under the one it depends on (the pc
88	// boundaries under --trigger pc); `dev` hides it unless ANDESIM_DEV is set.
89	struct OptRow {
90	  const char* flag;
91	  const char* tag;
92	  const char* brief;
93	  int indent;
94	  bool dev;
95	};
96	constexpr OptRow kRunOpts[] = {
97	    {"--mode fast|cycle|hybrid", "REQUIRED", "which mode to run", 2, false},
98	    {"--trigger marker|pc", "REQUIRED for hybrid", "the ROI delimiter", 2, false},
99	    {"--pc-start <sym|0x>", "REQUIRED for --trigger pc", "ROI start boundary", 4, false},
100	    {"--pc-end <sym|0x>", "REQUIRED for --trigger pc", "ROI end boundary", 4, false},
101	    {"--engine <id>", "", "pick an engine, e.g. vsim:ax45mpv_premium (default: the sole one)", 2, false},
102	    {"--mem-size <spec>", "", "guest RAM, e.g. 256M / 2G (max 2G; fast/hybrid)", 2, false},
103	    {"--verify", "", "cross-check the hybrid run against a QEMU oracle", 2, false},
104	    {"--gdb", "", "pause at startup for a debugger (fast: QEMU stub; cycle: vsim JTAG + $ICEMAN; not hybrid)", 2, false},
105	    {"--gdb-port <port>", "", "override the --gdb port (fast 1234, cycle 9104)", 2, false},
106	    {"--cosim", "", "co-sim vs the QEMU oracle: hybrid (ROI checkpoints) or cycle (lock-step)", 2, true},
107	    {"--cosim-interval <N>", "", "hybrid: checkpoint every N retired insns (default 10000)", 2, true},
108	    {"--cosim-refine", "", "hybrid: narrow the diverging window ~16x/pass", 2, true},
109	    {"--cosim-max-records <K>", "", "cycle lock-step: stop after K records (0 = until exit)", 2, true},
110	    {"-- <args...>", "", "forward everything after -- verbatim to the engine", 2, false},
111	};
112	
113	// A major command line at column 0: `name   brief`.
114	void print_major(std::FILE* out, const char* name, const char* brief) {
115	  std::fprintf(out, "%-7s %s\n", name, brief);
116	}
117	
118	// A subcommand/target line, indented two under its command: `  name   brief`.
119	void print_sub(std::FILE* out, const char* name, const char* brief) {
120	  std::fprintf(out, "  %-9s %s\n", name, brief);
121	}
122	
123	// An option line: `<indent>--flag    [TAG  ]brief`, flags aligned to a column.
124	void print_opt(std::FILE* out, const OptRow& o) {
125	  char left[96];
126	  std::snprintf(left, sizeof left, "%*s%s", o.indent, "", o.flag);
127	  if (o.tag[0])
128	    std::fprintf(out, "%-29s %s  %s\n", left, o.tag, o.brief);
129	  else
130	    std::fprintf(out, "%-29s %s\n", left, o.brief);
131	}
132	
133	// `run`: major line, the mode subcommands, then the option list (dev options
134	// only under ANDESIM_DEV). Shared by the top-level tree and `run --help`.
135	void print_run_block(std::FILE* out) {
136	  print_major(out, "run", "run one simulation");
137	  for (const ModeRow& m : kRunModes) print_sub(out, m.name, m.brief);
138	  std::fputs("\n", out);
139	  for (const OptRow& o : kRunOpts) {
140	    if (o.dev && !is_dev_mode()) continue;
141	    print_opt(out, o);
142	  }
143	}
144	
145	void print_list_block(std::FILE* out) {
146	  print_major(out, "list", "list what is available");
147	  for (const TargetRow& t : kListTargets) {
148	    if (t.dev && !is_dev_mode()) continue;
149	    print_sub(out, t.name, t.brief);
150	  }
151	}
152	
153	void print_doctor_block(std::FILE* out) {
154	  print_major(out, "doctor", "check toolchain + fixtures are present");
155	}
156	
157	// Top-level `andesim --help`: the whole tree -- every major command, its
158	// subcommands, and run's full option list, so one screen shows everything.
159	void print_usage(std::FILE* out) {
160	  std::fputs("usage: andesim <command> [options] <ELF> [-- <engine args>]\n\n",
161	             out);
162	  std::fputs("Multi-engine driver for the Andes simulators (QEMU + vsim).\n\n",
163	             out);
164	  print_run_block(out);
165	  std::fputs("\n", out);
166	  print_list_block(out);
167	  std::fputs("\n", out);
168	  print_doctor_block(out);
169	  std::fputs(
170	      "\n'andesim run --help' / 'andesim list --help' for per-command "
171	      "detail.\n",
172	      out);
173	}
174	
175	// Per-command `andesim <cmd> --help`: the matching slice of the same tree.
176	void print_subcommand_help(const Subcommand& sc, std::FILE* out) {
177	  if (sc.name == "run") { print_run_block(out); return; }
178	  if (sc.name == "list") { print_list_block(out); return; }
179	  if (sc.name == "doctor") { print_doctor_block(out); return; }
180	  // A Hidden/unfinished command: a stable usage line, no advertised detail.
181	  std::fprintf(out, "usage: andesim %.*s [args...]\n",
182	               static_cast<int>(sc.name.size()), sc.name.data());
183	}
184	
185	}  // namespace
186	
187	int main(int argc, char** argv) {
188	  using namespace andes_sim;
189	
190	  Cli cli = parse_cli(argc, argv);
191	  if (!cli.error.empty()) {
192	    std::fprintf(stderr, "andesim: %s\n", cli.error.c_str());
193	    return 2;
194	  }
195	
196	  if (cli.subcommand.empty()) {  // no command, or top-level -h
197	    if (cli.help) {
198	      print_usage(stdout);
199	      return 0;
200	    }
201	    print_usage(stderr);
202	    return 2;
203	  }
204	
205	  const Subcommand* sc = find(cli.subcommand);
206	  if (!sc) {
207	    std::fprintf(stderr, "andesim: unknown command '%s'\n\n",
208	                 cli.subcommand.c_str());
209	    print_usage(stderr);
210	    return 2;
211	  }
212	
213	  if (cli.help) {
214	    print_subcommand_help(*sc, stdout);
215	    return 0;
216	  }
217	
218	  if (cli.subcommand == "list") return cmd_list(cli);
219	  if (cli.subcommand == "doctor") return cmd_doctor(cli);
220	  if (cli.subcommand == "run") return cmd_run(cli);
221	
222	  // Remaining subcommands stub out until their feature lands. Resolve the repo
223	  // root so the discovery path stays live and observable.
224	  std::string root;
225	  try {
226	    root = repo_root().string();
227	  } catch (const std::exception& e) {
228	    root = std::string("<unknown: ") + e.what() + ">";
229	  }
230	  std::fprintf(stderr, "andesim %s: not yet implemented (repo root: %s)\n",
231	               cli.subcommand.c_str(), root.c_str());
232	  return 3;
233	}
