59	                                std::string& err) {
60	  err.clear();
61	  LegTriggerArgs out;
62	  if (t.kind == "marker") return out;  // markers detected by plugin/vsim, not argv
63	
64	  const bool fast = role == "fast-leg";
65	  const bool accurate = role == "accurate-leg";
66	  if (!fast && !accurate) return out;  // other roles carry no trigger args
67	
68	  // Required-param lookup. A missing key is a caller bug; surface it (don't
69	  // throw) so plan_argvs can report which step failed.
70	  auto param = [&](const char* key) -> const std::string* {
71	    auto it = t.params.find(key);
72	    if (it == t.params.end()) {
73	      err = "trigger '" + t.kind + "' missing param '" + key + "'";
74	      return nullptr;
75	    }
76	    return &it->second;
77	  };
78	
79	  if (t.kind == "pc") {
80	    if (fast) {
81	      if (const std::string* p = param("enter_pc"))
82	        out.plugin_suffix = ",enter_pc=" + *p;
83	    } else if (const std::string* p = param("exit_pc")) {
84	      out.extra = {"--hybrid-exit-pc", *p};
85	    }
86	    return out;
87	  }
88	  if (t.kind == "icount") {
89	    if (fast) {
90	      if (const std::string* p = param("qemu_icount"))
91	        out.plugin_suffix = ",icount=" + *p;
92	    } else if (const std::string* p = param("vsim_icount")) {
93	      out.extra = {"--hybrid-icount", *p};
94	    }
95	    return out;
96	  }
97	
98	  // verify oracle leg (verify_oracle F4): a pure-QEMU drain at the ROI exit
99	  // boundary, sampling at vsim's actual halt pc (drain_pc -- the DMI halt
100	  // lands a few insns past the trigger, and the comparison is only valid at
101	  // the same architectural point). qemu-only: the oracle plan has no
102	  // accurate leg.
103	  if (t.kind == "verify-marker" || t.kind == "verify-pc") {
104	    if (!fast) return out;
105	    std::string suffix = ",exit_marker=1";
106	    if (t.kind == "verify-pc") {
107	      const std::string* p = param("exit_pc");
108	      if (!p) return out;
109	      suffix = ",exit_pc=" + *p;
110	    }
111	    if (const std::string* p = param("drain_pc"))
112	      out.plugin_suffix = suffix + ",drain_pc=" + *p;
113	    return out;
114	  }
115	
116	  // cosim oracle leg (cosim_roi F4): pure QEMU arms at the ROI entry and
117	  // drains at the vsim checkpoints' retire deltas (`counts`, pre-joined
118	  // "a:b:c"; the last entry is the final exit-state drain). qemu-only: the
119	  // oracle plan has no accurate leg.
120	  if (t.kind == "cosim-marker" || t.kind == "cosim-pc") {
121	    if (!fast) return out;
122	    std::string suffix = ",cosim_marker=1";
123	    if (t.kind == "cosim-pc") {
124	      const std::string* p = param("enter_pc");
125	      if (!p) return out;
126	      suffix = ",cosim_pc=" + *p;
127	    }
128	    if (const std::string* p = param("counts"))
129	      out.plugin_suffix = suffix + ",cosim_counts=" + *p;
130	    return out;
131	  }
132	
133	  err = "unknown trigger kind '" + t.kind + "'";
134	  return out;
135	}
