137	std::vector<std::vector<std::string>> plan_argvs(
138	    const Plan& plan, const std::vector<EngineDescriptor>& engines,
139	    const std::string& workdir, const RuntimeCtx& ctx, std::string& err) {
140	  std::vector<std::vector<std::string>> out;
141	  out.reserve(plan.steps.size());
142	  std::string prev_state_out;  // empty for the cold first leg
143	
144	  // hw-config sync: {vlen} comes from the accurate-leg engine's descriptor.
145	  long vlen = 0;
146	  for (const Step& s : plan.steps)
147	    if (s.role == "accurate-leg")
148	      if (const EngineDescriptor* e = find_engine(engines, s.engine_id))
149	        if (e->vlen > 0) vlen = e->vlen;
150	  const std::string vlen_str = std::to_string(synced_vlen(vlen));
151	
152	  for (size_t i = 0; i < plan.steps.size(); ++i) {
153	    const Step& step = plan.steps[i];
154	    const EngineDescriptor* eng = find_engine(engines, step.engine_id);
155	    if (!eng) {
156	      err = "plan step " + std::to_string(i) + ": unknown engine '" +
157	            step.engine_id + "'";
158	      return {};
159	    }
160	    const std::vector<std::string>* tmpl = eng->invoke_for(step.role);
161	    if (!tmpl) {
162	      err = "plan step " + std::to_string(i) + ": engine '" + step.engine_id +
163	            "' has no invoke template for role '" + step.role + "'";
164	      return {};
165	    }
166	
167	    std::string trig_err;
168	    const LegTriggerArgs lt = leg_trigger_args(step.trigger, step.role, trig_err);
169	    if (!trig_err.empty()) {
170	      err = "plan step " + std::to_string(i) + ": " + trig_err;
171	      return {};
172	    }
173	
174	    const std::string state_out = state_path(workdir, i);
175	    const std::map<std::string, std::string> m = {
176	        {"bin", eng->bin_path},
177	        {"elf", plan.elf},
178	        {"plugin", ctx.plugin_path},
179	        {"mmap", ctx.mmap_path},
180	        {"mmap_size", std::to_string(ctx.mem_size)},
181	        {"mmap_base", ctx.mmap_base},
182	        {"state_in", prev_state_out},
183	        {"state_out", state_out},
184	        {"trigger", lt.plugin_suffix},  // qemu plugin comma-suffix (empty for marker)
185	        {"vlen", vlen_str},
186	    };
187	    std::vector<std::string> argv = build_argv(*tmpl, m, err);
188	    if (!err.empty()) {
189	      err = "plan step " + std::to_string(i) + ": " + err;
190	      return {};
191	    }
192	    // Trigger's vsim tokens, then user-forwarded per-leg flags -- both verbatim
193	    // after the filled template (matches tests/e2e.sh's ordering).
194	    argv.insert(argv.end(), lt.extra.begin(), lt.extra.end());
195	    argv.insert(argv.end(), step.extra_args.begin(), step.extra_args.end());
196	    out.push_back(std::move(argv));
197	    prev_state_out = state_out;
198	  }
199	  err.clear();
200	  return out;
201	}
202	
203	PlanResult run_plan(const Plan& plan,
204	                    const std::vector<EngineDescriptor>& engines,
205	                    const PlanOptions& opts) {
206	  PlanResult res;
207	  if (plan.steps.empty()) {
208	    res.error = "plan has no steps";
209	    return res;
210	  }
211	
212	  // Acquire the shared mmap: allocate one (and own it) when none is pinned.
213	  std::string mmap_path = plan.mmap_path;
214	  const bool own_mmap = mmap_path.empty();
215	  if (own_mmap) {
216	    std::string err;
217	    // L26/F2: back the mmap with one V-scratch page above the program's RAM.
218	    mmap_path = allocate(physical_mmap_bytes(plan.mem_size), err);
219	    if (mmap_path.empty()) {
220	      res.error = err;
221	      return res;
222	    }
223	  }
224	
225	  // A private dir for the threaded drain files.
226	  std::error_code ec;
227	  fs::path workdir = fs::temp_directory_path(ec) / "andesim-plan-XXXXXX";
228	  std::string tmpl = workdir.string();
229	  std::vector<char> tbuf(tmpl.begin(), tmpl.end());
230	  tbuf.push_back('\0');
231	  const char* made = ::mkdtemp(tbuf.data());
232	  if (!made) {
233	    if (own_mmap) ::unlink(mmap_path.c_str());
234	    res.error = "failed to create plan work dir";
235	    return res;
236	  }
237	  const std::string wd = made;
238	
239	  RuntimeCtx ctx;
240	  ctx.mmap_path = mmap_path;
241	  // L26/F2: the legs (QEMU backend size, vsim --shared-mem-size) see the
242	  // PHYSICAL window -- program RAM plus the V-scratch page. The program's own
243	  // linker script still uses only --mem-size, so the scratch page sits above
244	  // everything it can address.
245	  ctx.mem_size = physical_mmap_bytes(plan.mem_size);
246	  ctx.plugin_path = resolve_plugin(opts.plugin_path);  // mmap_base keeps its "0x0" default
247	
248	  std::string err;
249	  const std::vector<std::vector<std::string>> argvs =
250	      plan_argvs(plan, engines, wd, ctx, err);
251	  if (!err.empty()) {
252	    res.error = err;
253	  } else {
254	    for (size_t i = 0; i < argvs.size(); ++i) {
255	      const RunResult r = run_process(argvs[i], opts.timeout_ms);
256	      if (r.spawn_failed) {
257	        res.error = "plan step " + std::to_string(i) + ": failed to spawn";
258	        break;
259	      }
260	      if (r.timed_out) {
261	        res.error = "plan step " + std::to_string(i) + ": timed out after " +
262	                    std::to_string(opts.timeout_ms) + " ms";
263	        break;
264	      }
265	      if (r.rc != opts.expect_rc) {
266	        res.error = plan_step_rc_error(i, plan.steps[i], opts.expect_rc, r.rc);
267	        break;
268	      }
269	      const StateFile sf = read_state_file(state_path(wd, i));
270	      if (!sf.ok()) {
271	        res.error = "plan step " + std::to_string(i) + ": " + sf.error;
272	        break;
273	      }
274	      // cosim checkpoints (`<state_out>.ckpts` stream, cosim_redesign F3):
275	      // read them back now, before the workdir teardown deletes the file.
276	      std::vector<hybrid_state_v1> ckpts;
277	      const std::string stream_p = state_path(wd, i) + ".ckpts";
278	      if (fs::exists(stream_p, ec)) {
279	        StateStream cs = read_state_stream(stream_p);
280	        if (!cs.ok()) {
281	          res.error = "plan step " + std::to_string(i) + ": " + cs.error;
282	          break;
283	        }
284	        ckpts = std::move(cs.records);
285	      }
286	      res.phases.push_back(
287	          {sf.st.mcycle, sf.st.minstret, r.out, sf.st, std::move(ckpts)});
288	    }
289	  }
290	
291	  fs::remove_all(wd, ec);
292	  if (own_mmap) ::unlink(mmap_path.c_str());
293	  return res;
294	}
