45	// Resolve `path` to an absolute path. Returns the resolved string on success;
46	// on failure prints an error tagged with `ctx` and returns "".
47	std::string abs_elf(const std::string& path, const std::string& ctx) {
48	  std::error_code ec;
49	  std::string abs = fs::absolute(path, ec).string();
50	  if (ec) {
51	    std::fprintf(stderr, "andesim run %s: cannot resolve ELF '%s'\n",
52	                 ctx.c_str(), path.c_str());
53	    return "";
54	  }
55	  return abs;
56	}
