80	// The standalone-passthrough spine shared by `fast` and `cycle`: both take a
81	// single ELF, then exec the resolved engine standalone with `extra` (model
82	// flags the framework forwards, e.g. fast's -m) followed by the post-`--`
83	// args verbatim (inherit stdio, no timeout, propagate exit code). The only
84	// per-model differences -- which engine, and how it is selected -- are resolved
85	// by the caller; `model` here only labels the positional diagnostics.
86	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
87	                   const char* model,
88	                   const std::vector<std::string>& extra = {}) {
89	  if (int rc = check_one_elf(cli, model)) return rc;
90	  // QEMU's -bios flag searches its data directory for relative paths rather
91	  // than the CWD; resolve to absolute so both QEMU and vsim find the ELF.
92	  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
93	  if (elf.empty()) return 2;
94	  std::vector<std::string> args = extra;
95	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
96	  std::string err;
97	  int rc = run_passthrough(eng, "standalone", elf, args, err);
98	  if (!err.empty()) std::fprintf(stderr, "andesim run: %s\n", err.c_str());
99	  return rc;
100	}
