102	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Needs
103	// only the built-in qemu descriptor, so it resolves that directly rather than
104	// discover_engines(), which would spawn a --describe subprocess per Verilator
105	// build only to discard them all here.
106	int run_fast(const Cli& cli) {
107	  // fast is QEMU-only; an explicit engine must name it.
108	  if (!cli.engine.empty() && cli.engine != "qemu") {
109	    std::fprintf(stderr,
110	                 "andesim run --mode fast: engine must be 'qemu', got '%s'\n",
111	                 cli.engine.c_str());
112	    return 2;
113	  }
114	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
115	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
116	  std::string err;
117	  std::vector<std::string> extra = qemu_m_args(cli.mem_size, err);
118	  if (!err.empty()) {
119	    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
120	    return 2;
121	  }
122	  // --gdb: inject QEMU's built-in GDB stub and pause at startup.
123	  if (cli.gdb) {
124	    const std::string port = cli.gdb_port.empty() ? "1234" : cli.gdb_port;
125	    extra.push_back("-gdb");
126	    extra.push_back("tcp::" + port);
127	    extra.push_back("-S");
128	  }
129	  return run_standalone(cli, builtin_qemu(), "fast", extra);
130	}
