132	// Defined below run_accurate; --cosim on the cycle model dispatches to it.
133	int run_cosim_lockstep(const Cli& cli, const EngineDescriptor& eng);
134	
135	// Block until 127.0.0.1:`port` is LISTENing (or `timeout_ms` elapses). vsim opens
136	// its --jtag-port only after it has reset and halted the hart, so the debugger we
137	// exec next must not race ahead of it -- OpenOCD/ICEman do not retry the bitbang
138	// connect, and a missed connect leaves the session dead. Non-intrusive: scans
139	// /proc/net/tcp rather than connecting (a probe connection would land in vsim's
140	// single debugger slot). Returns false on timeout.
141	static bool wait_for_jtag_port(uint16_t port, int timeout_ms = 20000) {
142	  constexpr int kPollMs = 50;
143	  for (int waited = 0; waited <= timeout_ms; waited += kPollMs) {
144	    if (std::FILE* f = std::fopen("/proc/net/tcp", "re")) {
145	      char line[512];
146	      while (std::fgets(line, sizeof line, f)) {
147	        // cols: sl  local_address(IP:port hex)  rem_address  st  ...
148	        // "%*8x:%x" skips the 8-hex-digit IPv4 and reads the local port; the
149	        // 0A (TCP_LISTEN) filter also drops the non-hex header row.
150	        unsigned lport = 0, st = 0;
151	        if (std::sscanf(line, "%*s %*8x:%x %*s %x", &lport, &st) == 2
152	            && st == 0x0A && lport == port) {
153	          std::fclose(f);
154	          return true;
155	        }
156	      }
157	      std::fclose(f);
158	    }
159	    std::this_thread::sleep_for(std::chrono::milliseconds(kPollMs));
160	  }
161	  return false;
162	}
