164	// `run --mode cycle --gdb`: start vsim with --jtag-port 9104 in the background
165	// (the hart free-runs; ICEman halts it over the JTAG DTM on connect), then exec
166	// ICEman ($ICEMAN env var) with `-Z v5 -I virtual_dmi.cfg` in the foreground.
167	int run_cycle_gdb(const Cli& cli, const EngineDescriptor& eng) {
168	  const char* iceman = std::getenv("ICEMAN");
169	  if (!iceman || !*iceman) {
170	    std::fprintf(stderr,
171	                 "andesim run --mode cycle --gdb: $ICEMAN not set "
172	                 "(export ICEMAN=<path to ICEman binary>)\n");
173	    return 2;
174	  }
175	  // Build vsim argv from the standalone template, appending user passthrough
176	  // and the JTAG port flag.
177	  const std::string elf = abs_elf(cli.positional[0], "--mode cycle --gdb");
178	  if (elf.empty()) return 2;
179	  const std::string jtag_port = cli.gdb_port.empty() ? "9104" : cli.gdb_port;
180	  std::vector<std::string> vsim_pass = cli.passthrough;
181	  vsim_pass.push_back("--jtag-port");
182	  vsim_pass.push_back(jtag_port);
183	  std::string err;
184	  const std::vector<std::string> vsim_argv =
185	      passthrough_argv(eng, "standalone", elf, vsim_pass, err);
186	  if (!err.empty()) {
187	    std::fprintf(stderr, "andesim run --mode cycle --gdb: %s\n", err.c_str());
188	    return 2;
189	  }
190	  std::fprintf(stderr,
191	               "[andesim] --gdb: vsim JTAG on port %s, exec ICEman\n",
192	               jtag_port.c_str());
193	  if (fork_background(vsim_argv) < 0) {
194	    std::fprintf(stderr,
195	                 "andesim run --mode cycle --gdb: failed to fork vsim\n");
196	    return 1;
197	  }
198	  // vsim opens the JTAG port and the hart free-runs; ICEman halts it on connect.
199	  // Wait for the port to be LISTENing before launching the debugger (it does not
200	  // retry the bitbang connect). Numeric ports only; a non-numeric --gdb-port
201	  // (atoi -> 0) skips the wait and lets the engine reject it. Best-effort: warn
202	  // but launch anyway if it never appears.
203	  if (const int pnum = std::atoi(jtag_port.c_str());
204	      pnum > 0 && !wait_for_jtag_port(static_cast<uint16_t>(pnum)))
205	    std::fprintf(stderr,
206	                 "[andesim] --gdb: warning: vsim JTAG port %s not LISTENing "
207	                 "after 20s; launching the debugger anyway\n",
208	                 jtag_port.c_str());
209	  // -I virtual_dmi.cfg selects ICEman's remote_bitbang interface (host
210	  // localhost, port 9104) instead of its default real-hardware adapter; without
211	  // it ICEman finds no adapter and exits. The cfg is found relative to the cwd
212	  // (repo root) in interface/; it pins port 9104, matching --jtag-port's default.
213	  return exec_passthrough({iceman, "-Z", "v5", "-I", "virtual_dmi.cfg"});
214	}
