216	// `run --mode cycle`: one cycle-accurate engine alone, from reset (no QEMU,
217	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
218	// engine's own output. Unlike fast, this must discover the Verilator build(s)
219	// to resolve the engine (explicit --engine, else the sole one).
220	int run_accurate(const Cli& cli) {
221	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
222	  // --describe subprocess per Verilator build only to fail on the argument.
223	  if (int rc = check_one_elf(cli, "cycle")) return rc;
224	  // --mem-size is validated but has nothing to size: the cycle engine always
225	  // models its full DRAM window. Say so instead of silently ignoring it.
226	  if (!cli.mem_size.empty()) {
227	    std::string se;
228	    if (parse_size(cli.mem_size, se); !se.empty()) {
229	      std::fprintf(stderr, "andesim run --mode cycle: --mem-size: %s\n",
230	                   se.c_str());
231	      return 2;
232	    }
233	    std::fprintf(stderr,
234	                 "[andesim] --mem-size: the cycle engine models its full "
235	                 "DRAM window; nothing to size\n");
236	  }
237	  Discovery disc = discover_engines();
238	  std::string err;
239	  const EngineDescriptor* eng =
240	      resolve_accurate_engine(disc.engines, cli.engine, err);
241	  if (!eng) {
242	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", err.c_str());
243	    // Surface why an expected engine may be absent (failed --describe, etc.).
244	    for (const std::string& w : disc.warnings)
245	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
246	    return 2;
247	  }
248	  // --cosim on the cycle model = lock-step DV co-sim against a QEMU oracle,
249	  // not a plain standalone run.
250	  if (cli.cosim) return run_cosim_lockstep(cli, *eng);
251	  if (cli.gdb) return run_cycle_gdb(cli, *eng);
252	  return run_standalone(cli, *eng, "cycle");
253	}
