255	// Parse --cosim-max-records: empty => 0 (unbounded; the oracle runs to program
256	// exit and defines the record count). Returns false + sets err on a bad value.
257	bool parse_cosim_max(const std::string& s, unsigned long long& out,
258	                     std::string& err) {
259	  out = 0;
260	  if (s.empty()) return true;
261	  char* end = nullptr;
262	  out = std::strtoull(s.c_str(), &end, 10);
263	  if (!end || *end != '\0') {
264	    err = "--cosim-max-records: want a non-negative integer, got '" + s + "'";
265	    return false;
266	  }
267	  return true;
268	}
