270	// `run --mode cycle --cosim`: lock-step DV co-sim (cosim_redesign F6, usage
271	// 1). Two independent boots of the same ELF -- the QEMU oracle (golden) and
272	// the vsim DUT -- each drain one full record per execution attempt from the
273	// arm pc; the streams are aligned by attempt index and diffed to localize the
274	// first diverging instruction. No handoff, no shared mmap. The oracle runs
275	// first (MHz-fast, defines the record count K); the DUT is then bounded to K
276	// so a diverged hart cannot run away.
277	int run_cosim_lockstep(const Cli& cli, const EngineDescriptor& eng) {
278	  auto fail = [](const std::string& msg) {
279	    std::fprintf(stderr, "andesim run --mode cycle --cosim: %s\n",
280	                 msg.c_str());
281	    return 2;
282	  };
283	  if (int rc = check_one_elf(cli, "cycle")) return rc;
284	
285	  std::error_code ec;
286	  const fs::path elf = fs::absolute(cli.positional[0], ec);
287	  if (ec || !fs::is_regular_file(elf, ec))
288	    return fail("ELF not found: " + cli.positional[0]);
289	  const std::string elf_path = elf.string();
290	
291	  // Arm pc: --pc-start (symbol or 0x addr) overrides the ELF entry default.
292	  std::string err;
293	  uint64_t arm_pc = 0;
294	  if (cli.pc_start.empty()) {
295	    arm_pc = elf_entry(elf_path, err);
296	    if (!err.empty()) return fail(err);
297	  } else {
298	    const std::string hex = resolve_pc(elf_path, cli.pc_start, err);
299	    if (!err.empty()) return fail(err);
300	    arm_pc = std::strtoull(hex.c_str(), nullptr, 16);
301	  }
302	  char arm_buf[32];
303	  std::snprintf(arm_buf, sizeof(arm_buf), "0x%llx",
304	                static_cast<unsigned long long>(arm_pc));
305	
306	  unsigned long long max_records = 0;
307	  if (!parse_cosim_max(cli.cosim_max_records, max_records, err))
308	    return fail(err);
309	
310	  // Workdir for the two record streams (removed on exit).
311	  const fs::path wd =
312	      fs::temp_directory_path() /
313	      ("andes-cosim-ls-" + std::to_string(::getpid()));
314	  fs::create_directories(wd, ec);
315	  const std::string oracle_stream = (wd / "oracle.ckpts").string();
316	  const std::string dut_stream = (wd / "dut.ckpts").string();
317	  auto cleanup = [&] { fs::remove_all(wd, ec); };
318	
319	  // Lock-step is slow on the DUT (a DMI step + full drain per attempt, tens
320	  // of attempts/s); give both legs a generous ceiling. --cosim-max-records
321	  // bounds the work; the timeout is only the runaway backstop.
322	  constexpr int kTimeoutMs = 1800 * 1000;
323	
324	  // ---- Leg 1: QEMU oracle (golden). Standalone andes machine + the
325	  // lock-step plugin; outfile IS the record stream. vlen syncs from the DUT
326	  // engine so the V-state widths match. ----
327	  const std::string plugin = [&] {
328	    if (const char* p = std::getenv("VSIM_PLUGIN"); p && *p) return std::string(p);
329	    return default_plugin_path().string();
330	  }();
331	  std::string plugin_arg = plugin + ",outfile=" + oracle_stream +
332	                           ",lockstep_pc=" + arm_buf;
333	  if (max_records != 0)
334	    plugin_arg += ",lockstep_max=" + std::to_string(max_records);
335	
336	  const std::string vlen = std::to_string(synced_vlen(eng.vlen));
337	  std::vector<std::string> qemu_argv = {
338	      builtin_qemu().bin_path, "-machine", "andes_ae350", "-cpu",
339	      "andes-ax45mpv,vlen=" + vlen, "-nographic", "-semihosting-config",
340	      "enable=on,target=native", "-bios", elf_path, "-plugin", plugin_arg};
341	
342	  std::fprintf(stderr,
343	               "[andesim] cosim lock-step: oracle (QEMU) boots from reset, "
344	               "arms at %s\n",
345	               arm_buf);
346	  const RunResult qr = run_process(qemu_argv, kTimeoutMs);
347	  if (qr.spawn_failed) { cleanup(); return fail("oracle: failed to spawn QEMU"); }
348	  if (qr.timed_out) { cleanup(); return fail("oracle: timed out"); }
349	  if (!qr.out.empty()) std::fwrite(qr.out.data(), 1, qr.out.size(), stdout);
350	
351	  const StateStream oracle = read_state_stream(oracle_stream);
352	  if (!oracle.ok()) { cleanup(); return fail("oracle: " + oracle.error); }
353	  if (oracle.records.empty()) {
354	    cleanup();
355	    return fail("oracle produced no records (arm pc " + std::string(arm_buf) +
356	                " never reached?)");
357	  }
358	  const unsigned long long k = oracle.records.size();
359	  std::fprintf(stderr,
360	               "[andesim] cosim lock-step: oracle drained %llu record(s); "
361	               "DUT (vsim) bounded to the same\n",
362	               k);
363	
364	  // ---- Leg 2: vsim DUT, bounded to the oracle's K records. ----
365	  std::vector<std::string> vsim_argv = {
366	      eng.bin_path,         elf_path,
367	      "--cosim-lockstep",   "--cosim-out",
368	      dut_stream,           "--cosim-arm-pc",
369	      arm_buf,              "--cosim-max-records",
370	      std::to_string(k)};
371	  const RunResult vr = run_process(vsim_argv, kTimeoutMs);
372	  if (vr.spawn_failed) { cleanup(); return fail("DUT: failed to spawn vsim"); }
373	  if (vr.timed_out) { cleanup(); return fail("DUT: timed out"); }
374	  if (!vr.out.empty()) std::fwrite(vr.out.data(), 1, vr.out.size(), stdout);
375	
376	  const StateStream dut = read_state_stream(dut_stream);
377	  if (!dut.ok()) { cleanup(); return fail("DUT: " + dut.error); }
378	
379	  // ---- Compare ----
380	  const LockstepResult cmp = compare_lockstep_streams(oracle.records, dut.records);
381	  cleanup();
382	
383	  if (!cmp.diverged) {
384	    std::printf(
385	        "[cosim] PASS: %zu records match (lock-step, 1 attempt/record)\n",
386	        cmp.matched);
387	    return 0;
388	  }
389	
390	  if (!cmp.length_mismatch.empty()) {
391	    std::fprintf(stderr, "[cosim] FAIL: %s\n", cmp.length_mismatch.c_str());
392	    std::fprintf(stderr,
393	                 "        first divergence is a control-flow split at attempt "
394	                 "%zu (after %zu matching)\n",
395	                 cmp.record, cmp.matched);
396	    return 1;
397	  }
398	
399	  const std::string osym = symbolize(elf_path, cmp.oracle_pc);
400	  const std::string dsym = symbolize(elf_path, cmp.dut_pc);
401	  std::fprintf(stderr,
402	               "[cosim] FAIL: first divergence at attempt %zu (after %zu "
403	               "matching)\n",
404	               cmp.record, cmp.matched);
405	  std::fprintf(stderr, "        pc  vsim=0x%llx  qemu=0x%llx%s%s\n",
406	               static_cast<unsigned long long>(cmp.dut_pc),
407	               static_cast<unsigned long long>(cmp.oracle_pc),
408	               dsym.empty() ? "" : ("   (" + dsym + ")").c_str(),
409	               (!osym.empty() && osym != dsym) ? (" oracle=(" + osym + ")").c_str()
410	                                               : "");
411	  for (const FieldDiff& d : cmp.diff.diffs)
412	    std::fprintf(stderr, "        %-8s vsim=0x%llx  qemu=0x%llx\n",
413	                 d.field.c_str(), d.got, d.ref);
414	  return 1;
415	}
