417	// `run --mode hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
418	// handoff (no QEMU2). The trigger (marker|pc) delimits the ROI; the cycle
419	// figure is the vsim mcycle minus QEMU1's drained mcycle. Replaces the Python
420	// driver's tests/e2e.sh delegation with a single window-cycle line.
421	int run_hybrid(const Cli& cli) {
422	  // Single diagnostic sink for the early-validation returns: prefix + exit 2.
423	  auto fail = [](const std::string& msg) {
424	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", msg.c_str());
425	    return 2;
426	  };
427	
428	  if (int rc = check_one_elf(cli, "hybrid")) return rc;
429	
430	  // Resolve to an absolute, existing path: a clean error beats a downstream
431	  // spawn failure, and pc-trigger resolution reads the ELF's .symtab.
432	  std::error_code ec;
433	  const fs::path elf = fs::absolute(cli.positional[0], ec);
434	  if (ec || !fs::is_regular_file(elf, ec))
435	    return fail("ELF not found: " + cli.positional[0]);
436	  const std::string elf_path = elf.string();
437	
438	  // Validate everything cheap BEFORE the expensive engine discovery, so a CLI
439	  // mistake fails fast without spawning a --describe per Verilator build.
440	  std::string err;
441	  const Trigger trig = hybrid_trigger(cli, elf_path, err);
442	  if (!err.empty()) return fail(err);
443	
444	  // hybrid_trigger has already guaranteed trig.kind is marker|pc (the only
445	  // hybrid triggers; simpoint/unknown returned an error above) -- exactly the
446	  // entry boundary --verify/--cosim need the oracle to arm on.
447	  unsigned long long cosim_interval = 10000;  // default per docs/archive/cosim_roi.md
448	  if (cli.cosim && !cli.cosim_interval.empty()) {
449	    char* end = nullptr;
450	    cosim_interval = std::strtoull(cli.cosim_interval.c_str(), &end, 10);
451	    if (!end || *end != '\0' || cli.cosim_interval.empty() ||
452	        cosim_interval == 0)
453	      return fail("--cosim-interval: want a positive integer, got '" +
454	                  cli.cosim_interval + "'");
455	  }
456	
457	  std::vector<std::string> vsim_extras = vsim_extra_args(cli, trig.kind, err);
458	  if (!err.empty()) return fail(err);
459	
460	  long long mem = 128LL * 1024 * 1024;  // shared mmap; --mem-size overrides
461	  if (!cli.mem_size.empty()) {
462	    std::string se;
463	    mem = parse_size(cli.mem_size, se);
464	    if (!se.empty()) return fail("--mem-size: " + se);
465	    // Early cap: QEMU's AE350 DRAM window is 2 GiB and the backend doubles as
466	    // guest RAM here. The physical mmap reserves one V-scratch page above the
467	    // program's RAM (L26/F2), so the usable --mem-size is 2 GiB minus that
468	    // page. Failing now beats allocating a huge mmap file first and letting
469	    // QEMU die late.
470	    if (mem > max_program_mem_bytes())
471	      return fail("--mem-size " + cli.mem_size +
472	                  " exceeds the AE350 DRAM window (2G minus the V-scratch "
473	                  "reservation)");
474	  }
475	
476	  // L26/F3: refuse a run whose static image would extend into the reserved
477	  // V-transport scratch page. Scheme D parks the scratch in the TOP page of the
478	  // physical mmap; a PT_LOAD segment reaching there means the ELF was linked for
479	  // more RAM than --mem-size grants, and QEMU would load it straight onto the
480	  // scratch -> silent corruption. Derive the page's start from
481	  // physical_mmap_bytes (the same sizing the mmap uses) rather than a bare
482	  // `mem`, so the threshold tracks the reservation shape instead of relying on
483	  // the +page/-page adjustments cancelling. ram_base is the fixed andes_ae350
484	  // DRAM base (0; see L10). Skipped when the ELF cannot be read -- downstream
485	  // reports it.
486	  {
487	    std::string e;
488	    const uint64_t top = elf_load_top(elf_path, e);
489	    const uint64_t scratch_gpa =
490	        static_cast<uint64_t>(physical_mmap_bytes(mem)) - HYBRID_V_SCRATCH_BYTES;
491	    if (e.empty() && top > scratch_gpa) {
492	      char msg[256];
493	      std::snprintf(msg, sizeof(msg),
494	                    "ELF static image ends at 0x%llx, overlapping the reserved "
495	                    "V-transport scratch page at 0x%llx (ram_base + --mem-size)"
496	                    "; raise --mem-size or shrink the image",
497	                    static_cast<unsigned long long>(top),
498	                    static_cast<unsigned long long>(scratch_gpa));
499	      return fail(msg);
500	    }
501	  }
502	
503	  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
504	  // or the sole cycle-accurate engine (reusing the F8 selector).
505	  Discovery disc = discover_engines();
506	  const EngineDescriptor* acc =
507	      resolve_accurate_engine(disc.engines, cli.engine, err);
508	  if (!acc) {
509	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", err.c_str());
510	    for (const std::string& w : disc.warnings)
511	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
512	    return 2;
513	  }
514	
515	  // ISA sync: both legs must agree on the base ISA width (rv32 engines
516	  // cannot share architectural state with the rv64 fast leg).
517	  if (std::string hw = hybrid_hw_check(*acc); !hw.empty()) return fail(hw);
518	
519	  Plan plan;
520	  plan.elf = elf_path;
521	  plan.mem_size = mem;
522	  Step qemu_step{"qemu", "fast-leg", trig};
523	  Step vsim_step{acc->id, "accurate-leg", trig};
524	  vsim_step.extra_args = std::move(vsim_extras);  // kanata + warmup, validated
525	  if (cli.cosim) {
526	    // Orthogonal to the trigger: the vsim leg drains a resumable checkpoint
527	    // to the <state_out>.ckpts stream every N retires (run_plan reads them
528	    // back).
529	    vsim_step.extra_args.push_back("--hybrid-cosim");
530	    vsim_step.extra_args.push_back(std::to_string(cosim_interval));
531	  }
532	  plan.steps = {qemu_step, vsim_step};
533	
534	  // Banner to stderr so the window-cycle result stands alone on stdout.
535	  // vlen is the synced value the fast leg inherits from the engine.
536	  std::fprintf(stderr,
537	               "[andesim] model=hybrid engine=%s vlen=%ld trigger=%s fixture=%s\n",
538	               acc->id.c_str(), synced_vlen(acc->vlen), trig.kind.c_str(),
539	               elf.stem().string().c_str());
540	
541	  const PlanResult r = run_plan(plan, disc.engines);
542	  if (!r.ok()) {
543	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", r.error.c_str());
544	    return 1;
545	  }
546	  // Relay each leg's stdout verbatim: the program's own prints (QEMU1 phase-1
547	  // output, then anything the ROI wrote on vsim) belong to the user.
548	  for (const PhaseResult& p : r.phases)
549	    if (!p.out.empty()) std::fwrite(p.out.data(), 1, p.out.size(), stdout);
550	  // phases[0] = QEMU1 drain, [1] = vsim drain; the kernel/window figure is the
551	  // vsim mcycle delta. Suppressed under --cosim: every checkpoint adds a DMI
552	  // halt + drain + resume to the vsim leg, so the delta no longer measures
553	  // the kernel (a --cosim run answers "where diverged", not "how many cycles").
554	  if (!cli.cosim) {
555	    const unsigned long long q_mc = r.phases[0].mcycle;
556	    const unsigned long long v_mc = r.phases[1].mcycle;
557	    std::printf("[%s window_cycles] %llu  (vsim mcycle=%llu - qemu mcycle=%llu)\n",
558	                trig.kind.c_str(), v_mc - q_mc, v_mc, q_mc);
559	  }
560	
561	  // --verify (verify_oracle F4, default off): re-run the ELF on pure QEMU
562	  // with the plugin draining at the ROI exit boundary, sampling at vsim's
563	  // halt pc, and diff the two drains in-process. The oracle plan gets its
564	  // own fresh mmap: reusing the main run's would boot the oracle on the
565	  // hybrid run's leftover memory. Its stdout is dropped -- the program's
566	  // output was already relayed from the main run.
567	  if (cli.verify) {
568	    char pcbuf[32];
569	    std::snprintf(pcbuf, sizeof(pcbuf), "0x%llx",
570	                  static_cast<unsigned long long>(r.phases[1].st.pc));
571	    Trigger vtrig;
572	    vtrig.kind = "verify-" + trig.kind;
573	    if (trig.kind == "pc") vtrig.params["exit_pc"] = trig.params.at("exit_pc");
574	    vtrig.params["drain_pc"] = pcbuf;
575	
576	    Plan vplan;
577	    vplan.elf = elf_path;
578	    vplan.mem_size = mem;
579	    vplan.steps = {Step{"qemu", "fast-leg", vtrig}};
580	
581	    std::fprintf(stderr,
582	                 "[andesim] verify: oracle leg (pure QEMU drains at the ROI "
583	                 "exit, pc=%s)\n",
584	                 pcbuf);
585	    const PlanResult vr = run_plan(vplan, disc.engines);
586	    if (!vr.ok()) {
587	      std::fprintf(stderr, "andesim run --verify: %s\n", vr.error.c_str());
588	      return 1;
589	    }
590	    const DiffReport d = diff_states(vr.phases[0].st, r.phases[1].st);
591	    print_diff_report(d);
592	    if (!d.ok()) {
593	      std::fprintf(stderr,
594	                   "andesim run --verify: vsim drain diverges from the "
595	                   "QEMU oracle\n");
596	      return 1;
597	    }
598	    std::printf("[verify] PASS: vsim drain matches the QEMU oracle\n");
599	  }
600	
601	  // --cosim (cosim_roi F4, default off, dev): re-run the ELF on pure QEMU
602	  // with the plugin draining at the vsim checkpoints' retire deltas, then
603	  // diff checkpoint k against checkpoint k and the final drains. minstret is
604	  // restored from the entry state on resume, so `checkpoint.minstret -
605	  // entry.minstret` is the exact post-entry retire count -- both engines
606	  // sample the SAME architectural points, and the first mismatching window
607	  // brackets the divergence. Fresh mmap for the oracle (clean memory);
608	  // stdout dropped (already relayed from the main run).
609	  //
610	  // --cosim-refine (cosim_redesign F7): when set, after the coarse window is
611	  // found the driver re-runs QEMU1->vsim with explicit targets subdividing it
612	  // ~16x per pass (the vsim leg finishes at the last target, so each pass is
613	  // bounded), re-running the oracle at the vsim leg's achieved deltas, until
614	  // the window shrinks to the halt slack. QEMU1 is deterministic, so each pass
615	  // re-derives the same entry state -- no mmap snapshot needed.
616	  if (cli.cosim) {
617	    const unsigned long long m0 = r.phases[0].st.minstret;
618	
619	    // Flatten a leg's checkpoints + final drain into (state, absolute-delta)
620	    // lists. False on a zero/non-ascending delta (a corrupt leg).
621	    auto collect = [&](const PhaseResult& leg,
622	                       std::vector<hybrid_state_v1>& states,
623	                       std::vector<unsigned long long>& deltas) -> bool {
624	      states.clear();
625	      deltas.clear();
626	      for (const hybrid_state_v1& c : leg.checkpoints) {
627	        const unsigned long long d = c.minstret - m0;
628	        if (d == 0 || (!deltas.empty() && d <= deltas.back())) return false;
629	        states.push_back(c);
630	        deltas.push_back(d);
631	      }
632	      const unsigned long long df = leg.st.minstret - m0;
633	      if (df == 0 || (!deltas.empty() && df <= deltas.back())) return false;
634	      states.push_back(leg.st);
635	      deltas.push_back(df);
636	      return true;
637	    };
638	
639	    auto join = [](const auto& xs) {
640	      std::string s;
641	      for (size_t i = 0; i < xs.size(); ++i)
642	        s += (i ? ":" : "") + std::to_string(xs[i]);
643	      return s;
644	    };
645	
646	    // Oracle: pure QEMU draining at the given absolute deltas. Returns its
647	    // states (checkpoints + final, length == counts.size()) or nullopt.
648	    auto run_oracle = [&](const std::vector<unsigned long long>& counts)
649	        -> std::optional<std::vector<hybrid_state_v1>> {
650	      Trigger ot;
651	      ot.kind = "cosim-" + trig.kind;
652	      if (trig.kind == "pc") ot.params["enter_pc"] = trig.params.at("enter_pc");
653	      ot.params["counts"] = join(counts);
654	      Plan op;
655	      op.elf = elf_path;
656	      op.mem_size = mem;
657	      op.steps = {Step{"qemu", "fast-leg", ot}};
658	      const PlanResult orr = run_plan(op, disc.engines);
659	      if (!orr.ok()) {
660	        std::fprintf(stderr, "andesim run --cosim: %s\n", orr.error.c_str());
661	        return std::nullopt;
662	      }
663	      std::vector<hybrid_state_v1> os = orr.phases[0].checkpoints;
664	      os.push_back(orr.phases[0].st);
665	      if (os.size() != counts.size()) {
666	        std::fprintf(stderr,
667	                     "andesim run --cosim: oracle returned %zu states, "
668	                     "want %zu\n",
669	                     os.size(), counts.size());
670	        return std::nullopt;
671	      }
672	      return os;
673	    };
674	
675	    // First index where two aligned state lists differ (trap cause excluded:
676	    // the hybrid ROI is trap-free by contract).
677	    auto first_div = [](const std::vector<hybrid_state_v1>& os,
678	                        const std::vector<hybrid_state_v1>& vs)
679	        -> std::optional<size_t> {
680	      for (size_t i = 0; i < os.size() && i < vs.size(); ++i)
681	        if (!diff_states(os[i], vs[i]).ok()) return i;
682	      return std::nullopt;
683	    };
684	
685	    // ---- pass 1: the interval checkpoints from the main hybrid run ----
686	    std::vector<hybrid_state_v1> vstates;
687	    std::vector<unsigned long long> vdeltas;
688	    if (!collect(r.phases[1], vstates, vdeltas)) {
689	      std::fprintf(stderr,
690	                   "andesim run --cosim: non-ascending vsim checkpoint "
691	                   "deltas (corrupt leg?)\n");
692	      return 1;
693	    }
694	    std::fprintf(stderr,
695	                 "[andesim] cosim: oracle leg (pure QEMU, %zu sample(s))\n",
696	                 vdeltas.size());
697	    const auto ostates = run_oracle(vdeltas);
698	    if (!ostates) return 1;
699	
700	    auto div = first_div(*ostates, vstates);
701	    if (!div) {
702	      std::printf("[cosim] PASS: %zu checkpoint(s) + final state match the "
703	                  "QEMU oracle (interval %llu, %llu ROI retires)\n",
704	                  vstates.size() - 1, cosim_interval, vdeltas.back());
705	      std::printf("PASS: --mode hybrid --trigger %s (%s)\n",
706	                  trig.kind.c_str(), elf.stem().string().c_str());
707	      return 0;
708	    }
709	
710	    // Coarse diverging window (lo, hi]; div_v/div_o are the states at hi.
711	    unsigned long long lo = (*div == 0) ? 0 : vdeltas[*div - 1];
712	    unsigned long long hi = vdeltas[*div];
713	    hybrid_state_v1 div_v = vstates[*div];
714	    hybrid_state_v1 div_o = (*ostates)[*div];
715	    DiffReport div_diff = diff_states(div_o, div_v);
716	
717	    // ---- refine: subdivide (lo, hi] until it reaches the halt-slack floor.
718	    // Targets must stay >= kSpacing apart so the vsim halt overshoot cannot
719	    // reorder the achieved deltas; below that the haltreq checkpoint cannot
720	    // resolve further (use --mode cycle --cosim for exact single-stepping).
721	    if (cli.cosim_refine) {
722	      constexpr unsigned long long kSpacing = 8;
723	      constexpr int kFanout = 16;
724	      int pass = 1;
725	      while (hi - lo > kSpacing) {
726	        const std::vector<uint64_t> targets =
727	            subdivide_window(lo, hi, kFanout, kSpacing);
728	        if (targets.size() < 2) break;
729	        std::fprintf(stderr,
730	                     "[andesim] cosim-refine pass %d: window (%llu, %llu], "
731	                     "%zu probes\n",
732	                     ++pass, lo, hi, targets.size());
733	
734	        Step q{"qemu", "fast-leg", trig};
735	        Step v{acc->id, "accurate-leg", trig};
736	        v.extra_args = {"--hybrid-cosim-at", join(targets)};
737	        Plan p;
738	        p.elf = elf_path;
739	        p.mem_size = mem;
740	        p.steps = {q, v};
741	        const PlanResult pr = run_plan(p, disc.engines);
742	        if (!pr.ok()) {
743	          std::fprintf(stderr, "andesim run --cosim-refine: %s\n",
744	                       pr.error.c_str());
745	          return 1;
746	        }
747	        std::vector<hybrid_state_v1> rv;
748	        std::vector<unsigned long long> rd;
749	        if (!collect(pr.phases[1], rv, rd)) {
750	          std::fprintf(stderr,
751	                       "andesim run --cosim-refine: non-ascending vsim "
752	                       "deltas (halt slack exceeded the probe spacing?)\n");
753	          break;  // report the best window found so far
754	        }
755	        const auto ro = run_oracle(rd);
756	        if (!ro) return 1;
757	        const auto rdiv = first_div(*ro, rv);
758	        if (!rdiv) break;  // no narrower split resolved; keep current window
759	
760	        const unsigned long long nlo = (*rdiv == 0) ? lo : rd[*rdiv - 1];
761	        const unsigned long long nhi = rd[*rdiv];
762	        if (nhi >= hi && nlo <= lo) break;  // no progress
763	        lo = nlo;
764	        hi = nhi;
765	        div_v = rv[*rdiv];
766	        div_o = (*ro)[*rdiv];
767	        div_diff = diff_states(div_o, div_v);
768	      }
769	    }
770	
771	    // ---- report the (narrowed) diverging window ----
772	    print_diff_report(div_diff);
773	    const std::string sym = symbolize(elf_path, div_v.pc);
774	    std::fprintf(stderr,
775	                 "[cosim] FAIL: divergence in retires %llu..%llu after entry "
776	                 "(%llu insn window)%s\n",
777	                 lo, hi, hi - lo, cli.cosim_refine ? ", narrowed" : "");
778	    std::fprintf(stderr, "        at retire ~%llu: pc vsim=0x%llx qemu=0x%llx%s\n",
779	                 hi, static_cast<unsigned long long>(div_v.pc),
780	                 static_cast<unsigned long long>(div_o.pc),
781	                 sym.empty() ? "" : ("   (" + sym + ")").c_str());
782	    if (cli.cosim_refine && hi - lo > 8)
783	      std::fprintf(stderr,
784	                   "        (window at the halt-slack floor; for the exact "
785	                   "instruction use --mode cycle --cosim on a reset testbench)\n");
786	    return 1;
787	  }
788	
789	  std::printf("PASS: --mode hybrid --trigger %s (%s)\n", trig.kind.c_str(),
790	              elf.stem().string().c_str());
791	  return 0;
792	}
