796	int cmd_run(const Cli& cli) {
797	  if (cli.model.empty()) {
798	    std::fprintf(stderr,
799	                 "andesim run: --mode fast|cycle|hybrid is required "
800	                 "(pick the composition; see 'andesim run --help')\n");
801	    return 2;
802	  }
803	  if (!find_model(cli.model)) {
804	    std::fprintf(stderr,
805	                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
806	                 cli.model.c_str());
807	    return 2;
808	  }
809	  if (!cli.gdb_port.empty() && !cli.gdb) {
810	    std::fprintf(stderr, "andesim run: --gdb-port requires --gdb\n");
811	    return 2;
812	  }
813	  // --gdb is an interactive debugging aid; the hybrid handoff runs QEMU1 then
814	  // vsim sequentially in a pipeline and cannot pause for a debugger to attach.
815	  if (cli.gdb && cli.model == "hybrid") {
816	    std::fprintf(stderr,
817	                 "andesim run: --gdb is not supported with --mode hybrid\n");
818	    return 2;
819	  }
820	  // --verify re-runs the workload against a QEMU oracle -- only the hybrid
821	  // composition has a second engine to check.
822	  if (cli.verify && cli.model != "hybrid") {
823	    std::fprintf(stderr,
824	                 "andesim run: --verify requires --mode hybrid (the %s "
825	                 "model has nothing to cross-check)\n",
826	                 cli.model.c_str());
827	    return 2;
828	  }
829	  // --cosim cross-checks against a QEMU oracle: hybrid (ROI window checkpoints)
830	  // or cycle (lock-step from reset). The fast model is QEMU itself -- nothing
831	  // to check.
832	  if (cli.cosim && cli.model == "fast") {
833	    std::fprintf(stderr,
834	                 "andesim run: --cosim requires --mode hybrid or cycle "
835	                 "(fast is QEMU itself, nothing to cross-check)\n");
836	    return 2;
837	  }
838	  if (cli.cosim && cli.verify) {
839	    std::fprintf(stderr,
840	                 "andesim run: --verify and --cosim are exclusive (--cosim "
841	                 "already cross-checks the final state)\n");
842	    return 2;
843	  }
844	  // --cosim-interval is the hybrid ROI knob; --cosim-max-records is the
845	  // cycle lock-step knob. Each requires --cosim and its own model.
846	  if (!cli.cosim && !cli.cosim_interval.empty()) {
847	    std::fprintf(stderr, "andesim run: --cosim-interval requires --cosim\n");
848	    return 2;
849	  }
850	  if (!cli.cosim_interval.empty() && cli.model != "hybrid") {
851	    std::fprintf(stderr,
852	                 "andesim run: --cosim-interval applies to --mode hybrid "
853	                 "(cycle lock-step uses --cosim-max-records)\n");
854	    return 2;
855	  }
856	  if (!cli.cosim_max_records.empty() && !(cli.cosim && cli.model == "cycle")) {
857	    std::fprintf(stderr,
858	                 "andesim run: --cosim-max-records requires --mode cycle "
859	                 "--cosim (lock-step)\n");
860	    return 2;
861	  }
862	  // --cosim-refine narrows the hybrid ROI window; it has no meaning for the
863	  // cycle lock-step (already exact) or without --cosim.
864	  if (cli.cosim_refine && !(cli.cosim && cli.model == "hybrid")) {
865	    std::fprintf(stderr,
866	                 "andesim run: --cosim-refine requires --mode hybrid "
867	                 "--cosim (cycle lock-step is already instruction-exact)\n");
868	    return 2;
869	  }
870	  // --trigger / --pc-start / --pc-end delimit the hybrid ROI window; fast and
871	  // cycle run the whole program and would silently drop them, handing back a
872	  // whole-program figure for the window the user asked for. Reject instead.
873	  // Exception: --pc-start doubles as the cycle lock-step arm pc under
874	  // --mode cycle --cosim (run_cosim_lockstep), so it stays valid there.
875	  if (!cli.trigger.empty() && cli.model != "hybrid") {
876	    std::fprintf(stderr,
877	                 "andesim run: --trigger applies only to --mode hybrid "
878	                 "(the ROI delimiter); fast/cycle run the whole program\n");
879	    return 2;
880	  }
881	  if (!cli.pc_end.empty() && cli.model != "hybrid") {
882	    std::fprintf(stderr,
883	                 "andesim run: --pc-end applies only to --mode hybrid "
884	                 "--trigger pc\n");
885	    return 2;
886	  }
887	  if (!cli.pc_start.empty() && cli.model != "hybrid" &&
888	      !(cli.model == "cycle" && cli.cosim)) {
889	    std::fprintf(stderr,
890	                 "andesim run: --pc-start applies only to --mode hybrid "
891	                 "--trigger pc (or --mode cycle --cosim)\n");
892	    return 2;
893	  }
894	  if (cli.model == "fast") return run_fast(cli);
895	  if (cli.model == "cycle") return run_accurate(cli);
896	  return run_hybrid(cli);  // model validated above; only hybrid remains
897	}
